if [ "${1:-}" = --uninstall ]; then
  "$SETTINGS" forget "$0" || exit 2
  rm -rf "$BASE"
  rm -f "$WWEV"
  exit 0
fi
[ "$(id -u)" = 0 ] || { log '请以 root 运行'; exit 2; }
