  if gzip -dc "$WORK/client.gz" > "$WORK/client" &&
     [ "$(sha256sum "$WORK/client" | awk '{print $1}')" = "$CLIENT_SHA" ]; then
    chmod 700 "$WORK/client" && mv -f "$WORK/client" "$BIN"
