worker() {
  ensure_install || return 2
  SESSION=/tmp/lx06-db-session.$$
  (umask 077; mkdir "$SESSION") || return 2
  FIFO=$SESSION/mic
  LT=; LC=
  cleanup() {
    trap - EXIT
    [ -n "$LC" ] && kill -TERM "$LC" 2>/dev/null
    [ -n "$LT" ] && kill -TERM "$LT" 2>/dev/null
    rm -f "$FIFO" "$SESSION/ready"
    rmdir "$SESSION" 2>/dev/null
    :
  }
  trap cleanup EXIT
  trap 'exit 0' TERM INT
  mkfifo "$FIFO" || return 2
  export DB_MIC_FIFO="$FIFO" DB_ALSA_DEVICE=notify LD_LIBRARY_PATH=/usr/lib
  GLIBC_TUNABLES=glibc.pthread.rseq=0 "$XA/processed-mic-read" --name "db-$$" --ready-file "$SESSION/ready" > "$FIFO" &
  LT=$!
  GLIBC_TUNABLES=glibc.pthread.rseq=0 "$SETTINGS" run "$0" /bin/sh -c '
    if [ "$DB_BARGE_ANY" = 1 ]; then export DB_INTERRUPT=""; fi
    exec "$1"
  ' doubao "$BIN" &
  LC=$!
  log "session worker=$$ client=$LC reader=$LT"
  # Every exit is handled here; a cloud/network error is not a keeper failure.
  while kill -0 "$LC" 2>/dev/null; do
    if ! kill -0 "$LT" 2>/dev/null; then
      sleep .2
      kill -0 "$LC" 2>/dev/null && { log 'microphone exited; closing session'; return 0; }
      break
    fi
    sleep .2
  done
  wait "$LC"; result=$?; LC=
  log "session client exit=$result"
  return 0
}
local_session() {
  ticket=${2:-}
  epoch=; expires=
  case "$ticket" in
    *:*) epoch=${ticket%%:*}; expires=${ticket#*:};;
    '') ;;
    *) return 2;;
  esac
  [ -z "$ticket" ] || { [ -n "$epoch" ] && [ -n "$expires" ]; } || return 2
  "$SETTINGS" run "$0" sh -c '
    export LX06_DIALOG_LIGHTS=1 LX06_SESSION_MAX_SECONDS="$DB_MAX_SECONDS"
    if [ -n "$4" ]; then
      exec "$1/session-run" run-local doubao_watch.sh "$4" "$5" sh "$2" --session-worker
    fi
    exec "$1/session-run" run doubao_watch.sh sh "$2" --session-worker
  ' lx06 "$XA" "$0" "${1:-}" "$epoch" "$expires" &
  SPID=$!
  wait "$SPID"; result=$?; SPID=
  log "session closed result=$result"
  return 0
}
resident_cleanup() {
  trap - EXIT
  [ -n "$SPID" ] && { kill -TERM "$SPID" 2>/dev/null; wait "$SPID"; }
  rm -f "$WWEV"
  :
}
[ -x "$XA/session-run" ] && [ -x "$XA/processed-mic-read" ] || { log '固件缺少会话管理或麦克风组件'; exit 2; }
if [ "${1:-}" != --session-worker ]; then
  ensure_install || { log '安装失败：请检查 DATA 剩余空间及安装文件权限'; exit 2; }
fi
case "${1:-}" in
  --session-worker) worker; exit 0;;
  --wakeup) [ "$#" -le 3 ] || exit 2; local_session "${2:-}" "${3:-}"; exit $?;;
  '') ;;
  *) log '不支持的参数'; exit 2;;
esac
exec 8>/tmp/lx06-db-resident.lock
flock -n 8 || exit 0
trap resident_cleanup EXIT
trap 'exit 0' TERM INT
rm -f "$WWEV"
log '豆包常驻就绪：本地唤醒、连续对话、话中打断、结束语/超时退出、官方优先'
while :; do
  if [ -s "$WWEV" ]; then
    IFS=' ' read -r word score stamp ticket extra < "$WWEV" || :
    rm -f "$WWEV"
    read -r uptime rest < /proc/uptime
    case "$stamp" in ''|*[!0-9.]*) stamp=0;; esac
    if [ -n "$word" ] && [ "${uptime%%.*}" -ge "${stamp%%.*}" ] &&
       [ "$(( ${uptime%%.*} - ${stamp%%.*} ))" -le 3 ]; then
      [ -n "$extra" ] || local_session "$word" "$ticket"
    else log 'discard stale local event'; fi
  fi
  sleep .1
done
